def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    if isinstance(cmd, list):
        cmd = tuple(cmd)

    if len(cmd) == 1 and isinstance(cmd[0], str) and cmd[0].startswith('#'):
        script_path = cmd[0]
        return ('"python.exe"', script_path), cmd[1:]

    if len(cmd) >= 2:
        if isinstance(cmd[0], str) and cmd[0].startswith('#'):
            shebang = cmd[0]
            script_path = cmd[1:]
            return (shebang, '"' + script_path[0] + '"'), script_path[1:]
        elif isinstance(cmd[0], str) and cmd[0].startswith('"') and cmd[-1].endswith('"'):
            shebang = cmd[0][1:-1]
            script_path = cmd[1:-1]
            return (shebang, '"' + script_path[0] + '"'), script_path[1:]
        else:
            return cmd, ()
