import functools

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    @functools.wraps(cache)
    def memoized_function(*args, **kwargs):
        if key:
            _key = key(*args, **kwargs)
        else:
            _key = args + tuple(sorted(kwargs.items()))

        if lock:
            with lock:
                result = cache.get(_key)
                if result is None:
                    result = cache[_key] = cache(*args, **kwargs)
        else:
            result = cache.get(_key)
            if result is None:
                result = cache[_key] = cache(*args, **kwargs)

        return result

    return memoized_function
