def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    if validate_objects:
        for e in [self] + list(self.children):
            if not e.validate():
                self.log('Invalid storage root element:', e.id)
                if show_warnings:
                    print(f'Invalid storage root element: {e}')
                return len([e]), len([e])

    if check_digests:
        for e in [self] + list(self.children):
            if e.digest and e.digest != self.digest:
                self.log('Invalid storage root element digest:', e.id)
                if show_warnings:
                    print(f'Invalid storage root element digest: {e}')
                return len([e]), len([e])

    num_objects = len([e] + list(self.children))
    good_objects = len([e for e in [self] + list(self.children) if e.validate() and e.digest == self.digest])
    return num_objects, good_objects
