    for path in find_paths:
        if path in existing_patterns:
            continue
        if '*' in path or '?' in path:
            glob_pattern = re.escape(path).replace('\\*', '').replace('\\?', '')
        else:
            glob_pattern = path
        new_patterns.append(glob_pattern)

    return new_patterns
