def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xrd

    try:
        data: Union[Dict, xrd.URLsRIFF] = json.loads(document)

        if isinstance(data, dict):
            return data
        elif isinstance(data, xrd.URLsRIFF):
            return {key: value.to_dict() for key, value in data.items()}
        else:
            raise ValueError("Unsupported data format")
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger: {e}")
